mapper.update:
UPDATE tool_version
SET status = 'PUBLISHED',
    published_at = #{now},
    updated_at = #{now}
WHERE id = #{versionId}
  AND tool_catalog_id = #{toolCatalogId}
  AND status = 'DRAFT'

mapper.select:
SELECT COALESCE(MAX(version_number), 0) + 1
FROM tool_version
WHERE tool_catalog_id = #{toolCatalogId}
